			"tiers": []map[string]any{{"up_to": 10, "unit_amount": "1"}, {"unit_amount": "2"}}}
	}
	withTiers := func(ts ...map[string]any) map[string]any { b := base(); b["tiers"] = ts; return b }
	bad := map[string]map[string]any{
		"licensed plan": func() map[string]any { b := base(); delete(b, "usage_type"); return b }(),
		"no tiers_mode": func() map[string]any { b := base(); delete(b, "tiers_mode"); return b }(),
		"unknown mode": func() map[string]any { b := base(); b["tiers_mode"] = "stairs"; return b }(),
		"tiers_mode alone": func() map[string]any { b := base(); delete(b, "tiers"); return b }(),
		"empty tiers": func() map[string]any { b := base(); b["tiers"] = []any{}; return b }(),
		"unsorted": withTiers(map[string]any{"up_to": 50, "unit_amount": "1"}, map[string]any{"up_to": 10, "unit_amount": "1"}, map[string]any{"unit_amount": "1"}),
		"fractional up_to": withTiers(map[string]any{"up_to": 10.5, "unit_amount": "1"}, map[string]any{"unit_amount": "1"}),
		"string up_to": withTiers(map[string]any{"up_to": "10", "unit_amount": "1"}, map[string]any{"unit_amount": "1"}),
		"negative amount": withTiers(map[string]any{"up_to": 10, "unit_amount": "-1"}, map[string]any{"unit_amount": "1"}),
		"missing unit_amount": withTiers(map[string]any{"up_to": 10}, map[string]any{"unit_amount": "1"}),
		"last tier capped": withTiers(map[string]any{"up_to": 10, "unit_amount": "1"}),
		"unbounded in the middle": withTiers(map[string]any{"unit_amount": "1"}, map[string]any{"up_to": 10, "unit_amount": "1"}),
	}
	for name, body := range bad {
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_tiers" {
			t.Errorf("%s: %s", name, r)
		}
	}
}
